using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<int> a(n);
    for (int& x : a) cin >> x;

    vector<long long> required(m + 1);
    __int128 totalRequired = 0;

    for (int i = 1; i <= m; ++i) {
        cin >> required[i];
        totalRequired += required[i];
    }

    if (totalRequired == 0) {
        cout << "YES\n";
        return 0;
    }

    if (totalRequired > n) {
        cout << "NO\n";
        return 0;
    }

    const long long requiredLength = static_cast<long long>(totalRequired);
    vector<long long> count(m + 1, 0);
    int left = 0;

    for (int right = 0; right < n; ++right) {
        int x = a[right];

        if (x < 1 || x > m || required[x] == 0) {
            while (left < right) {
                int value = a[left++];
                if (value >= 1 && value <= m)
                    --count[value];
            }
            left = right + 1;
            continue;
        }

        ++count[x];

        while (count[x] > required[x]) {
            int value = a[left++];
            --count[value];
        }

        if (right - left + 1 == requiredLength) {
            cout << "YES\n";
            return 0;
        }
    }

    cout << "NO\n";
    return 0;
}

