#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n, m;
    cin >> n >> m;

    vector<long long> a(n);
    for (long long &x : a) cin >> x;

    vector<long long> required(m + 1);
    long long windowSize = 0;
    for (long long i = 1; i <= m; ++i) {
        cin >> required[i];
        windowSize += required[i];
    }

    if (windowSize == 0) {
        cout << "YES\n";
        return 0;
    }

    if (windowSize > n) {
        cout << "NO\n";
        return 0;
    }

    vector<long long> count(m + 1, 0);
    long long mismatches = 0;
    for (long long i = 1; i <= m; ++i) {
        if (required[i] != 0) ++mismatches;
    }

    long long invalid = 0;

    auto update = [&](long long value, long long delta) {
        if (value < 1 || value > m) {
            invalid += delta;
            return;
        }

        if (count[value] != required[value]) --mismatches;
        count[value] += delta;
        if (count[value] != required[value]) ++mismatches;
    };

    for (long long right = 0; right < n; ++right) {
        update(a[right], 1);

        if (right >= windowSize) {
            update(a[right - windowSize], -1);
        }

        if (right + 1 >= windowSize && invalid == 0 && mismatches == 0) {
            cout << "YES\n";
            return 0;
        }
    }

    cout << "NO\n";
    return 0;
}

